<script>
  // ─── TAB SWITCHING ───
  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const tab = btn.dataset.tab;
      document.querySelectorAll('.tab-btn').forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-selected', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');
      document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
      const panel = document.getElementById('tab-' + tab);
      if (panel) panel.classList.add('active');
    });
  });

  // ─── FILTER PILLS ───
  document.querySelectorAll('.pill').forEach(pill => {
    pill.addEventListener('click', () => {
      document.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      // Animate the grid
      const activePanel = document.querySelector('.tab-panel.active');
      if (activePanel) {
        activePanel.style.opacity = '0';
        activePanel.style.transform = 'translateY(8px)';
        setTimeout(() => {
          activePanel.style.transition = 'opacity 0.25s ease, transform 0.25s ease';
          activePanel.style.opacity = '1';
          activePanel.style.transform = 'none';
        }, 80);
      }
    });
  });

  // ─── FLOWS TOGGLE ───
  document.querySelectorAll('.toggle-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.toggle-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const mode = btn.dataset.mode;
      document.getElementById('mode-videos').style.display = mode === 'videos' ? 'block' : 'none';
      document.getElementById('mode-prototype').style.display = mode === 'prototype' ? 'block' : 'none';
    });
  });

  // ─── STATS COUNTER ───
  function formatNumber(n) {
    if (n >= 1000) return n.toLocaleString();
    return n.toString();
  }

  function animateCounter(el, target, duration) {
    const start = performance.now();
    const easeOut = t => 1 - Math.pow(1 - t, 3);
    function tick(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      const value = Math.round(easeOut(progress) * target);
      el.textContent = formatNumber(value);
      if (progress < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  const statsObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const counters = entry.target.querySelectorAll('[data-target]');
        counters.forEach((counter, i) => {
          const target = parseInt(counter.dataset.target, 10);
          setTimeout(() => animateCounter(counter, target, 1800), i * 200);
        });
        // Trigger fade-in for stat cards
        entry.target.querySelectorAll('.fade-in').forEach((el, i) => {
          setTimeout(() => el.classList.add('visible'), i * 120);
        });
        statsObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });

  const statsSection = document.getElementById('stats-section');
  if (statsSection) statsObserver.observe(statsSection);

  // ─── GENERIC FADE-IN ON SCROLL ───
  const fadeObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        fadeObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15 });

  document.querySelectorAll('.fade-in').forEach(el => fadeObserver.observe(el));

  // ─── MOBILE MENU (simple toggle) ───
  document.querySelector('.nav-menu-btn')?.addEventListener('click', () => {
    const links = document.querySelector('.nav-links');
    if (links) {
      const isVisible = links.style.display === 'flex';
      links.style.display = isVisible ? 'none' : 'flex';
      links.style.flexDirection = 'column';
      links.style.position = 'absolute';
      links.style.top = '60px';
      links.style.left = '0';
      links.style.right = '0';
      links.style.background = 'white';
      links.style.padding = '16px 24px 24px';
      links.style.borderBottom = '1px solid #e5e5e5';
      links.style.boxShadow = '0 8px 24px rgba(0,0,0,0.08)';
    }
  });
</script>
